def mockups(mk: Callable[[str], Path]) -> list[tuple]:
    blocks: list[tuple] = [("p", MOCKUP_INTRO)]
    for png, caption, intro in SCREENS:
        blocks += [("p", intro), ("fig", mk(png), caption)]
    return blocks
